changeSet.sql:
ALTER TABLE im_profile RENAME TO im_role;
ALTER SEQUENCE im_profile_id RENAME TO im_role_id;
ALTER TABLE im_role RENAME CONSTRAINT pk_profile TO pk_role;
ALTER TABLE im_profile_permission RENAME TO im_role_permission;
ALTER TABLE im_role_permission RENAME COLUMN id_profile TO id_role;
ALTER TABLE im_role_permission RENAME CONSTRAINT pk_profile_permission TO pk_role_permission;

ALTER TABLE im_user ADD COLUMN is_administrator BOOLEAN NOT NULL DEFAULT false;
UPDATE im_user SET is_administrator = true
 WHERE id_profile = (SELECT id FROM im_role WHERE name = 'ADMIN_ORGANIZATION');

ALTER TABLE im_sector_allocation ADD COLUMN id_role BIGINT;
UPDATE im_sector_allocation a SET id_role = u.id_profile
  FROM im_user u
 WHERE u.id = a.id_user AND u.id_profile IS NOT NULL;
UPDATE im_sector_allocation
   SET id_role = (SELECT id FROM im_role WHERE name = 'GESTOR_SETOR')
 WHERE id_user IN (SELECT id FROM im_user WHERE is_administrator = true);
UPDATE im_sector_allocation
   SET id_role = (SELECT id FROM im_role WHERE name = 'CONSULTA')
 WHERE id_role IS NULL;
ALTER TABLE im_sector_allocation ALTER COLUMN id_role SET NOT NULL;
ALTER TABLE im_sector_allocation ADD CONSTRAINT fk_sector_allocation_role
    FOREIGN KEY (id_role) REFERENCES im_role (id);

ALTER TABLE im_user DROP COLUMN id_profile;
DELETE FROM im_role_permission
 WHERE id_role = (SELECT id FROM im_role WHERE name = 'ADMIN_ORGANIZATION')
    OR id_permission = (SELECT id FROM im_permission WHERE name = 'ADMIN');
DELETE FROM im_role WHERE name = 'ADMIN_ORGANIZATION';
DELETE FROM im_permission WHERE name = 'ADMIN';

UPDATE im_permission
   SET description = 'Gerencia os inventários do setor (criar, editar, finalizar, importar e remover itens) e aloca usuários nele.'
 WHERE name = 'MANAGE_SECTOR';
UPDATE im_permission
   SET description = 'Opera os itens do setor: valida (escaneia) e registra observações.'
 WHERE name = 'MANAGE_ITEM';

UPDATE im_role SET name = 'Gestor de Setor',
                   description = 'Gerencia os inventários e os usuários do setor.'
 WHERE name = 'GESTOR_SETOR';
UPDATE im_role SET name = 'Operador de Campo',
                   description = 'Realiza o levantamento em campo: valida itens e registra observações.'
 WHERE name = 'OPERADOR_CAMPO';
UPDATE im_role SET name = 'Consulta',
                   description = 'Somente consulta as informações do setor.'
 WHERE name = 'CONSULTA';
